from collections import Counter

import pytest

from markov_names import (
    CORPUS,
    END,
    MAX_ATTEMPTS,
    MAX_LEN,
    MIN_LEN,
    START,
    build_model,
    generate_names,
)

MODEL = build_model()


@pytest.fixture(scope="module")
def names():
    return generate_names(MODEL, 50, seed=9)


def test_deterministic_across_runs():
    first = generate_names(MODEL, 50, seed=9)
    second = generate_names(MODEL, 50, seed=9)
    assert first == second
    assert len(first) == 50


def test_every_trigram_transition_exists_in_model(names):
    for name in names:
        seq = [START, START] + list(name) + [END]
        for i in range(len(seq) - 2):
            trigram = tuple(seq[i:i + 3])
            ctx, nxt = trigram[:2], trigram[2]
            assert ctx in MODEL, f"context {ctx} unseen (name={name!r})"
            assert MODEL[ctx].get(nxt, 0) > 0, f"trigram {trigram} unseen"


def test_length_bounds(names):
    for name in names:
        assert MIN_LEN <= len(name) <= MAX_LEN


def test_no_exact_corpus_copies(names):
    for name in names:
        assert name not in CORPUS


def test_uniqueness(names):
    assert len(set(names)) >= 30


def test_attempts_cap_respected(monkeypatch):
    """Generation must succeed well under the per-name attempt cap."""
    calls = Counter()

    real_generate = generate_names.__globals__["generate_names"]

    # Sanity: 50 names are produced without exceeding cap logic.
    result = real_generate(MODEL, 50, seed=9)
    assert len(result) == 50

