def is_valid(name):
    return MIN_LEN <= len(name) <= MAX_LEN and name not in CORPUS


def generate_names(model, n, seed, max_attempts=MAX_ATTEMPTS):
    """Generate n valid names deterministically for a given seed.

    Each accepted name may consume at most `max_attempts` samples.
    """
    rng = random.Random(seed)
    names = []
    while len(names) < n:
        for _ in range(max_attempts):
            candidate = generate_name(model, rng)
            if is_valid(candidate):
                names.append(candidate)
                break
        else:
            raise RuntimeError(
                f"no valid name after {max_attempts} attempts"
            )
    return names

